  [ [[v5748eaic9o3t]] ] = { t = [[压制与挣脱]], q = [=[一个生物想用[[擒抱]]战技来[[压制]]对手，通常需要进行两次战技检定（第一次发动擒抱，第二次压制）。如果你被压制，是否也需要成功两次检定才能挣脱，一次对付擒抱，另一次对付压制？]=], a = [=[否。生物被压制时，会获得被擒抱状态的这种更严重的版本，这两种状态不会叠加（如压制状态的描述所述）。这意味着你不会同时承受被擒抱和被压制两者的减值，但这也意味着被压制取代了被擒抱状态，而不是在其之上累加。因此，你只需成功进行一次战技检定或[[脱逃]]检定，就能同时挣脱擒抱和压制。]=], book = [[核心规则书]], date = [[2011/01/06]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9o3t]], cat = [[FAQ]], ai = false, pages = { [[擒抱]], [[压制]] } },
