  [ [[v5748eaic9uhm]] ] = { t = [[高等虚招]], q = [=[[[高等虚招]]说，目标会失去AC的敏捷加值，直到我的下一个回合开始，而不只是对我的下一次攻击。这只是针对我的攻击吗（到下一个回合之前大概也就只有我的下一次攻击而已），还是对我的盟友也有效？]=], a = [=[高等虚招使目标对任何人的所有近战攻击都失去敏捷加值，直到你的下一个回合开始，而不只是对你的攻击。除非某个虚招能力特别提到远程攻击（比如[[远距虚招]]专长），否则它只会使目标对近战攻击失去敏捷加值。]=], book = [[核心规则书]], date = [[2016/01/04]], paizo = [[https://paizo.com/paizo/faq/v5748nruor1fm#v5748eaic9uhm]], cat = [[FAQ]], ai = true, pages = { [[高等虚招]], [[特殊攻击]] } },
